-- End-to-end scenario using the real sample plans + STVs (fixtures generated by scripts/gen-sql-fixtures.ts).
-- Sites: 1 Jahra, 2 Egaila, 3 Salmiya, 4 Hawally, 5 Jahra DC

create function public.t_assert(cond boolean, msg text) returns void language plpgsql as $$
begin
  if cond is distinct from true then raise exception 'ASSERT FAILED: %', msg; end if;
end $$;
grant execute on function public.t_assert(boolean, text) to authenticated;

create function public.t_expect_error(p_sql text, p_like text) returns void language plpgsql as $$
begin
  execute p_sql;
  raise exception 'ASSERT FAILED: expected error like "%" from: %', p_like, p_sql;
exception when others then
  if sqlerrm not like '%' || p_like || '%' then
    if sqlerrm like 'ASSERT FAILED%' then raise; end if;
    raise exception 'ASSERT FAILED: expected error like "%" but got "%"', p_like, sqlerrm;
  end if;
end $$;
grant execute on function public.t_expect_error(text, text) to authenticated;

