-- ============ Plan vs dispatch reconciliation (the findings from the analysis) ============
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-00000000000b', false);
set role authenticated;
do $$
declare hleg uuid := (select leg_id from public.v_legs where ref = 'AL-00001' and to_site_id = 4);
        eleg uuid := (select leg_id from public.v_legs where ref = 'AL-00001' and to_site_id = 2);
begin
  perform public.t_assert((select array_agg(item_code order by item_code) from public.v_leg_items where leg_id = hleg and dispatch_status = 'not_sent')
                          = array['1208373', '1209820', '3005622', '3005748'], 'Hawally: 4 not sent');
  perform public.t_assert((select count(*) from public.v_leg_items where leg_id = hleg and dispatch_status = 'ok') = 28, 'Hawally: 28 ok');
  perform public.t_assert((select dispatch_status from public.v_leg_items where leg_id = eleg and item_code = '1001676') = 'not_sent', 'Perrier juice not sent');
  perform public.t_assert((select dispatch_status from public.v_leg_items where leg_id = eleg and item_code = '1002390') = 'unplanned', 'Perrier water unplanned');
  perform public.t_assert((select dispatch_gap from public.v_leg_items where leg_id = eleg and item_code = '1202024') = -4, 'Indomie short 4');
  perform public.t_assert((select dispatch_status from public.v_leg_items where leg_id = eleg and item_code = '1210044') = 'short', 'Green forest short');
  perform public.t_assert((select status from public.v_legs where leg_id = hleg) = 'in_transit', 'hawally leg in transit');
  perform public.t_assert((select open_issues from public.v_legs where leg_id = hleg) = 4, 'hawally 4 issues');
  perform public.t_assert((select status from public.v_legs where ref = 'AL-00001' and to_site_id = 3) = 'awaiting_dispatch', 'salmiya awaiting');
  perform public.t_assert((select open_qty from public.v_legs where ref = 'AL-00002' and to_site_id = 4) = 1144, 'dc->hawally open 1144');
  -- today (30-09) all three STVs are past the 1-day receiving SLA -> every open line is flagged
  perform public.t_assert((select count(*) from public.v_discrepancies where kind = 'receipt_short') = 28 + 16 + 64, 'overdue receipt lines flagged');
end $$;
reset role;

