-- ============ Receipts by Hawally (new ERP code 304 auto-mapped) ============
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000004', false);
set role authenticated;
do $$
declare
  r1 jsonb := (select data from public.test_fx where name = 'stv_39126');
  pv jsonb;
begin
  -- receipt of 39126: all lines, but chocolate milk 250 of 259, plus an item that was never dispatched
  r1 := jsonb_set(r1, '{doc_no}', '"R-39126"');
  r1 := jsonb_set(r1, '{stv_date}', '"2026-09-17"');
  r1 := r1 || jsonb_build_object('from_code', '502', 'from_name', 'Hawally Allocation', 'to_code', '304', 'to_name', 'Hawally D.S');
  r1 := jsonb_set(r1, '{lines}', (
    select jsonb_agg(case when x->>'item_code' = '1002710' then jsonb_set(x, '{qty}', '250') else x end) || jsonb_build_array(jsonb_build_object('item_code', '9999999', 'qty', 3))
    from jsonb_array_elements(r1->'lines') x));
  pv := public.stv_preview(r1);
  perform public.t_assert(pv->>'direction' = 'receipt', 'receipt direction: ' || pv::text);
  perform public.t_assert((pv->'to'->>'is_new')::boolean and (pv->'to'->>'site_id')::int = 4, 'guessed 304 = Hawally DS');
  perform public.t_assert(pv->'dispatch_suggestions'->0->>'doc_no' = '39126', 'suggest 39126 first: ' || (pv->'dispatch_suggestions')::text);
  perform public.submit_stv(r1 || jsonb_build_object('link_dispatch_ids', jsonb_build_array(pv->'dispatch_suggestions'->0->>'stv_id')));
end $$;
select public.t_assert((select kind from public.erp_locations where code = '304') = 'ds' and (select auto_created from public.erp_locations where code = '304'), '304 auto created');
do $$
declare r2 jsonb := (select data from public.test_fx where name = 'stv_40493');
begin
